ulog_step n m k =
       if m = 0 then 0 
  else if n <= m then k else ulog_step n (2 * m) (SUC k)

ordz_seek m n c j =
  if c <= j then 0
  else if (n ** j) MOD m = 1 then j else ordz_seek m n c (SUC j)

poly_intro_rangeM n k c =
       do
         c0 <- zeroM c;
         if c0 then return T
         else do
                b1 <- poly_introM n k c;
                if b1 then do
                             j <- decM c;
                             poly_intro_rangeM n k j;
                           od
                else return F
              od
       od

sizeM n =
      do
        b0 <- zeroM n;
        b1 <- oneM n;
        if b0 \/ b1 then return 1
        else do
               x' <- halfM n;
               y' <- sizeM x';
               incM y';
             od
      od

power_ofM b n =
    do
       n0 <- zeroM n;
       n1 <- oneM n;
       b0 <- zeroM b;
       b1 <- oneM b;
       if n0 then return b0
       else if n1 then return T
       else if b0 then return (n0 \/ n1)
       else if b1 then return n1
       else do
              m' <- modM n b;
              gd <- zeroM m';
              if gd then
                 do
                    n' <- divM n b;
                    power_ofM b n';
                 od
              else return F
            od
    od

appendM l1 l2 =
      do
         gd <- nullM l1;
         if gd then return l2
         else do
                 h <- headM l1;
                 t <- tailM l1;
                 ls <- appendM t l2;
                 consM h ls;
              od
      od

snocM x ls =
       do
         gd <- nullM ls;
         if gd then consM x ls
         else do
                 h <- headM ls;
                 t <- tailM ls;
                 l <- snocM x t;
                 consM h l;
              od
       od

mexpM m b n =
      do
         m0 <- zeroM m;
         m1 <- oneM m;
         gd <- zeroM n;
         if m0 \/ m1 then return ((b ** n) MOD m)
         else if gd then return 1
         else do
                 b' <- msqM m b;
                 n' <- halfM n;
                 r  <- mexpM m b' n';
                 ifM (evenM n) (return r) (mmulM m b r);
              od
      od

ordz_seekM m n c j =
      do
         b0 <- leqM c j;
         if b0 then return 0
         else do
                x <- mexpM m n j;
                x1 <- oneM x;
                if x1 then return j
                else do
                       k <- incM j;
                       ordz_seekM m n c k;
                     od
              od
      od

param_seekM m c n k =
      do
         k0 <- zeroM k;
         if k0 then return bad
         else do
               b0 <- leqM c k;
              if b0 then return bad
              else do 
                     r <- modM n k;
                     r0 <- zeroM r;
                     if r0 then return (nice k)
                     else do 
                            z <- ordzM k n;
                            b1 <- leqM m z;
                            if b1 then return (good k)
                            else do
                                  j <- incM k;
                                  param_seekM m c n j;
                                od
                          od
                     od
              od
      od

poly_extendM p k =
      do
        k0 <- zeroM k;
        if k0 then return p
        else do
               q <- consM 0 p;
               j <- decM k;
               poly_extendM q j;
             od
      od

poly_eqM p q =
      do
        p0 <- nullM p;
        q0 <- nullM q;
        if p0 then return q0
        else if q0 then return p0
        else do
               h1 <- headM p;
               t1 <- tailM p;
               h2 <- headM q;
               t2 <- tailM q;
               e0 <- eqM h1 h2;
               if e0 then poly_eqM t1 t2
               else return F
             od
      od

poly_cmultM n c p =
      do
        p0 <- nullM p;
        if p0 then return []
        else do
               h <- headM p;
               t <- tailM p;
               k <- mmulM n c h;
               q <- poly_cmultM n c t;
               consM k q;
             od
      od

poly_addM n p q =
      do
        p0 <- nullM p;
        q0 <- nullM q;
        if p0 then return q
        else if q0 then return p
        else do
               h1 <- headM p;
               h2 <- headM q;
               t1 <- tailM p;
               t2 <- tailM q;
               h <- maddM n h1 h2;
               r <- poly_addM n t1 t2;
               consM h r;
             od
      od

poly_lastM p =
      do
        p0 <- nullM p;
        if p0 then return (LAST [])
        else do
                h <- headM p;
                t <- tailM p;
                t0 <- nullM t;
                if t0 then return h
                else poly_lastM t;
             od
      od

poly_frontM p =
      do
        p0 <- nullM p;
        if p0 then return (FRONT [])
        else do
                h <- headM p;
                t <- tailM p;
                t0 <- nullM t;
                if t0 then return []
                else do
                       q <- poly_frontM t;
                       consM h q
                     od
             od
      od

poly_multM n p q =
      do
        q0 <- nullM q;
        if q0 then return []
        else do
               h <- headM q;
               t <- tailM q;
               p1 <- poly_cmultM n h p;
               r <- poly_turnM p;
               p2 <- poly_multM n r t;
               poly_addM n p1 p2;
             od
      od

poly_expM n p j = 
      do
         j0 <- zeroM j;
         if j0 then
              do 
                 n1 <- oneM n;
                 if n1 then return []  
                 else consM 1 [] 
              od
         else do
                 p1 <- poly_sqM n p;
                 h <- halfM j;
                 q <- poly_expM n p1 h;
                 ifM (evenM j) (return q) (poly_multM n p q)
              od
      od

poly_get_coeffM p j = 
      do
        j0 <- zeroM j;
        if j0 then headM p
        else do
               q <- tailM p;
               i <- decM j;
               poly_get_coeffM q i;
             od
      od

poly_put_coeffM x p j = 
      do
        q <- tailM p;
        j0 <- zeroM j;
        if j0 then consM x q
        else do
               h <- headM p;
               i <- decM j;
               p1 <- poly_put_coeffM x q i;
               consM h p1;
             od
      od

expM b n =
      do
         gd <- zeroM n;
         if gd then return 1
         else do
                 b' <- sqM b;
                 n' <- halfM n;
                 r  <- expM b' n';
                 ifM (evenM n) (return r) (mulM b r);
              od
      od

shrinkM n k =
       do
          gd <- zeroM k;
          if gd then return n
          else do
                  n' <- halfM n;
                  k' <- decM k;
                  shrinkM n' k'
               od
       od

rootM k n =
       do
          k0 <- zeroM k;
          n0 <- zeroM n;
          if k0 then return (ROOT 0 n)
          else if n0 then return 0
          else do
                 n' <- shrinkM n k;
                 r  <- rootM k n';
                 x  <- twiceM r;
                 y  <- incM x;
                 z  <- expM y k;
                 b  <- leqM z n;
                 c  <- boolM b;
                 addM x c;
               od
       od

power_free_loopM n k =
      do
        k0 <- zeroM k;
        k1 <- oneM k;
        if k0 \/ k1 then return T
        else do
               r <- rootM k n;
               m  <- expM r k;
               gd <- eqM m n;
               if gd then return F
               else do
                      k' <- decM k;
                      power_free_loopM n k';
                    od
             od
      od

factor_seekM n c q =
    do
      b0 <- leqM c q;
      if b0 then return n
      else do
             b1 <- ifM (leqM q 1) (return F) (do r <- modM n q; r0 <- zeroM r od);
             if b1 then return q
             else do
                    p <- incM q;
                    factor_seekM n c p;
                  od
           od
    od

Feistel f      0  r ks w = w /\
    Feistel f (SUC n) r ks w =
      let (u,v) = Feistel f n r ks w; k = EL n ks in
        if SUC n = r then (u ?? f v k, v)
        else           (v, u ?? f v k)

Round      0  ks w = (w :block) /\
