rec_phi n = if n = 0 then 0
         else if n = 1 then 1
         else n - SIGMA rec_phi { m | m < n /\ m divides n}

!m n. m ** n = if n = 0 then 1 else if n = 1 then m
                 else if EVEN n then (m * m) ** HALF n
                 else m * ((m * m) ** (HALF n))

!s. FINITE s ==>
