  if n = r.sum.id \/ n NOTIN r.carrier then {} else {x}

mpoly_ring (r:'a ring) (s:'v set) :('a,'v) mpoly ring =
  let m = { p | mpoly r p /\ support r p ⊆ s } in
    <| carrier := m;
         sum := <| carrier := m; op := mpoly_add r; id := K r.sum.id |>;
         prod := <| carrier := m; op := mpoly_mul r; id := mpoly_one r |> |>

(poly_chop (r:'a ring) [] = []) /\
  (poly_chop (r:'a ring) (h:'a :: t:'a poly) =
   if zerop (h::t) then [] else (h:: poly_chop r t))

poly_ring (r:'a ring):'a poly ring =
   <| carrier := { p:'a poly | poly p };
          sum := <| carrier := { p:'a poly | poly p };
                         op := (\p q. chop (p || q));
                         id := []
                  |>;
         prod := <| carrier := { p:'a poly | poly p };
                         op := (\p q. chop (p o q));
                         id := chop [#1]
                  |>
    |>

(poly_coeff (r:'a ring) [] n = #0) /\
