dup r1 r2 r3= <|
    Q := {0;1;2;3;4;5};
    tf := (λs. case s of
            | 0 => Dec r2 (SOME 0) (SOME 1)
            | 1 => Dec r1 (SOME 2) (SOME 4)
            | 2 => Inc r2 (SOME 3)
            | 3 => Inc r3 (SOME 1)
            | 4 => Dec r3 (SOME 5) NONE
            | 5 => Inc r1 (SOME 4)
