group_auto_group (g:'a group) =
      <| carrier := group_auto_maps g;
              op := (\f1 f2. (f1 o f2) on G);
              id := I on G
       |>

field_auto_group (r:'a field) =
      <| carrier := field_auto_maps r;
              op := \f1 f2. (f1 o f2) on R;
              id := (I on R)
       |>

subfield_auto_group (r:'a field) (s:'a field) =
      <| carrier := subfield_auto_maps r s;
              op := (\f1 f2. (f1 o f2) on R);
              id := (I on R)
       |>

!n a. necklace n a =
        if n = 0 then {[]}
        else IMAGE (\(c,ls). c::ls) (count a CROSS necklace (n - 1) a)

!n a. monocoloured n a =
        if n = 0 then {[]}
        else IMAGE (\c. GENLIST (K c) n) (count a)

transpose (a:num, x, b:num, y) = if x < y then (x, a, y, b)
                                    else if y < x then (y, b, x, a)
                                    else (a, x, b, y)

!n t m. let p = step 0 t; q = step (SQRT n) t in
          tik n /\ ~square n /\ n = windmill t /\ ~is_ping t /\ m <= q ==>
          p < q /\
          if m < p then is_pung (hop m t)
          else if m = p then is_pong (hop m t)
          else if m < q then is_ping (hop m t)
          else ~is_ping (hop m t)

hop m (x,y,z) = if x < 2 * m * z
                   then (2 * m * z - x, z, y + m * x - m ** 2 * z)
                   else (x - 2 * m * z, y + m * x - m ** 2 * z, z)

!n. mills n = if tok n then {}
                 else if tik n /\ ~square n then mills_tik n
                 else mills n

!n. mills n = if zig n /\ ~square n then mills_zig n
                 else if zag n then {}
                 else mills n

!p. prime p /\ (p MOD 4 = 1) ==>
       let u = (1, 1, p DIV 4);
           n = iterate_period (zagier o flip) u
        in fixes flip (mills p) = {FUNPOW (zagier o flip) (n DIV 2) u}

!p. prime p /\ (p MOD 4 = 1) ==>
       let (x,y,z) = WHILE ($~ o found) (zagier o flip) (1,1,p DIV 4)
        in p = x ** 2 + (y + z) ** 2

!y z. zagier (0, y, z) =
        if z < y then (2 * z,z,y - z)
        else if 0 < y then (2 * y,y,z - y)
        else (0,z,0)

!x y. zagier (x, y, 0) =
        if x < y then (x, 0, y - x)
        else if x < 2 * y then (2 * y - x, y, x - y)
        else (x - 2 * y, x - y, y)

!y. zagier (1, y, 1) =
         if y = 0 then (1, 2, 0)
         else if y = 1 then (1, 1, 1)
         else if y = 2 then (3, 2, 0)
         else (3, 1, y - 2)

!x y z. (zagier o flip) (x, y, z) =
           if x < z - y then (x + 2 * y, y, z - y - x)
           else if x < 2 * z then (2 * z - x, z, x + y - z)
           else (x - 2 * z, x + y - z, z)

!z. (zagier o flip) (1,1,z) =
         if z = 0 then (1,2,0)
         else if z = 1 then (1,1,1)
         else if z = 2 then (3,2,0)
         else (3,1,z - 2)

!z. (zagier o flip) (0,1,z) =
         if z = 0 then (0,1,0)
         else (2,1,z - 1)

!y z. (zagier o flip) (0, y, z) =
         if 0 < z - y then (2 * y, y, z - y)
         else if 0 < z then (2 * z, z, y - z)
         else (0,y,0)

!x z. (zagier o flip) (x, 0, z) =
         if x < z then (x, 0, z - x)
         else if x < 2 * z then (2 * z - x, z, x - z)
         else (x - 2 * z, x - z, z)

!x y z. (flip o zagier) (x, y, z) =
           if x < y - z then (x + 2 * z, y - z - x, z)
           else if x < 2 * y then (2 * y - x, x + z - y, y)
           else (x - 2 * y, y, x + z - y)

zagier (x, y, z) =
    if x < y - z then (x + 2 * z, z, y - z - x)
    else if x < 2 * y then (2 * y - x, y, x + z - y) 
    else (x - 2 * y, x + z - y, y)

firstSet G (NT N :: rest) =
      if N ∈ FDOM G.rules then
        BIGUNION (IMAGE (firstSet G) (G.rules ' N)) ∪
        (if nullable G [NT N] then firstSet G rest
         else {})
      else {}

