(if cv_has_shape [SOME 0] v then INL (t1 (cv_snd v))
   else if cv_has_shape [NONE] v then INR (t2 (cv_snd v))
   else ARB) = to_sum t1 t2 v

to_sum t1 t2 (Num n) = ARB /\
  to_sum t1 t2 (Pair x y) =
    if x = Num 0 then INL (t1 y) else INR (t2 y)

!f:'a->'b->'c s t.
