    COUNTABLE {f x y | x IN s /\ y IN (t x)}

omega <= (x:'a ordinal) ==>
  { (y:'a ordinal) | preds y <<= preds x } =~
  { (y:'a ordinal) | preds y =~ preds x }

istopology { s | !e. e IN s ==>
                       (?a:'a ordinal b. e IN ival a b /\ ival a b SUBSET s) \/
                       ?b. e < b /\ !d. d < b ==> d IN s }

{p | p permutes (a INSERT s)} =
        IMAGE (\(b,p). swap(a,b) o p)
              {(b,p) | b IN a INSERT s /\ p IN {p | p permutes s}}

!xs xss e.
