metric_countable_covers (d :'a metric) (e :extreal) (sts :'a set set) =
      \a. {f | f IN (univ(:num) -> sts) /\ a SUBSET (BIGUNION (IMAGE f UNIV)) /\
               !i. Normal (set_diameter d (f i)) <= e}

!U. COUNTABLE {J | ?a b c d. a IN q_set /\ b IN q_set /\ c IN q_set /\ d IN q_set /\
                                 J = OPEN_interval (a,b) CROSS OPEN_interval (c,d) /\
                                 J SUBSET U}

sigma UNIV {s | open_in (mtop mr2) s} =
    sigma UNIV {J | ?a b c d. a IN q_set /\ b IN q_set /\ c IN q_set /\ d IN q_set /\
                              J = OPEN_interval (a,b) CROSS OPEN_interval (c,d)}

!sp sts. semiring (sp,sts) ==>
             subsets (smallest_ring sp sts) =
               {BIGUNION c | c SUBSET sts /\ FINITE c /\ disjoint c}

div_gcd a b =
    let d = gcd (Num a) b in
      if d = 0 \/ d = 1 then (a, b) else (a / &d, b DIV d)

dsize D =
      @N. (!n. n < N ==> D(n) < D(SUC n)) /\
          (!n. n >= N ==> (D(n) = D(N)))

!f:(real->bool)->real s.
        f has_bounded_setvariation_on s
        ==> bounded { f(interval[c,d]) | interval[c,d] SUBSET s}

!s. diameter s =
        if s = {} then (&0:real)
        else sup {abs(x - y) | x IN s /\ y IN s}

!s t:real->bool.
        is_interval s /\ is_interval t
        ==> is_interval {x + y | x IN s /\ y IN t}

!s t. setdist(s,t) =
          if (s = {}) \/ (t = {}) then (&0 :real)
          else inf {dist(x,y) | x IN s /\ y IN t}

set_diameter (d :'a metric) (s :'a set) =
      if s = {} then (0 :real)
      else sup {dist d (x,y) | x IN s /\ y IN s}

set_dist (d :'a metric) ((s,t) :'a set # 'a set) =
      if (s = {}) \/ (t = {}) then (0 :real)
      else inf {dist d (x,y) | x IN s /\ y IN t}

!m. mtopology (m:'a metric) =
       topology {u | u SUBSET mspace m /\
                     !x:'a. x IN u ==> ?r. &0 < r /\ mball m (x,r) SUBSET u}

NT c n = if c = 0 then n
           else if 100 < n then NT (c - 1) (n - 10)
           else NT (c + 1) (n + 11)

