(!c v1 v2. bir_eval_ifthenelse (SOME (BVal_Imm c)) (SOME v1) (SOME v2) =
     if (type_of_bir_imm c = Bit1) then (
       if (type_of_bir_val v1 <> type_of_bir_val v2) then NONE else
         if (c = Imm1 1w) then (SOME v1) else (SOME v2)
     ) else NONE) /\
