birs_symb_from_concst (SymbConcSt lbl env status) =
      <|
        bst_pc       := lbl;
        bst_environ  := BEnv env;
        bst_status   := status
      |>

birs_symb_from_symbst (SymbSymbSt lbl env pcond status) =
      <|
        bsst_pc       := lbl;
        bsst_environ  := env;
        bsst_pcond    := pcond;
        bsst_status   := status
      |>

birs_exec_stmt_assign v ex (st : birs_state_t) =
      case birs_eval_exp ex st.bsst_environ of
     | SOME (vaex, vaty) =>
         if vaty = bir_var_type v /\ (OPTION_BIND (st.bsst_environ (bir_var_name v)) type_of_bir_exp = SOME vaty) then
           {st with bsst_environ := (birs_update_env (bir_var_name v, vaex) st.bsst_environ)}
         else
           {birs_state_set_typeerror st}
     | NONE => {birs_state_set_typeerror st}

birs_exec_stmt_assert ex (st : birs_state_t) =
      case birs_eval_exp ex st.bsst_environ of
     | SOME (vaex, BType_Imm Bit1) =>
        {st with bsst_pcond := BExp_BinExp BIExp_And st.bsst_pcond vaex;
         (st with bsst_pcond := BExp_BinExp BIExp_And st.bsst_pcond (BExp_UnaryExp BIExp_Not vaex))
            with bsst_status := BST_AssertionViolated}
     | NONE => {birs_state_set_typeerror st}
     | _ => {birs_state_set_typeerror st}

birs_exec_stmt_assume ex (st : birs_state_t) =
      case birs_eval_exp ex st.bsst_environ of
     | SOME (vaex, BType_Imm Bit1) =>
        {st with bsst_pcond := BExp_BinExp BIExp_And st.bsst_pcond vaex;
         (st with bsst_pcond := BExp_BinExp BIExp_And st.bsst_pcond (BExp_UnaryExp BIExp_Not vaex))
            with bsst_status := BST_AssumptionViolated}
     | NONE => {birs_state_set_typeerror st}
     | _ => {birs_state_set_typeerror st}

bir_symb_rec_sbir prog =
    <|
      sr_val_true        := bir_val_true;
      sr_mk_exp_symb_f   := BExp_Den;
      sr_mk_exp_neg_f    := BExp_UnaryExp BIExp_Not;
      sr_mk_exp_conj_f   := BExp_BinExp BIExp_And;
      sr_mk_exp_eq_f     := \e1. if option_CASE (type_of_bir_exp e1) F bir_type_is_Mem then BExp_MemEq e1 else BExp_BinPred BIExp_Equal e1;

      sr_subst_f         := \(s,e). bir_exp_subst1 s e;


      sr_symbols_f       := bir_vars_of_exp;


      sr_typeof_val      := type_of_bir_val;
      sr_typeof_symb     := bir_var_type;
      sr_typeof_exp      := type_of_bir_exp;
      sr_ARB_val         := bir_val_default;


      sr_interpret_f     := birs_interpret_fun;

      sr_val_eq          := birs_val_eq;


      sr_step_conc       := birs_symb_to_concst o SND o (bir_exec_step prog) o birs_symb_from_concst;

      sr_step_symb       := (IMAGE birs_symb_to_symbst) o (birs_exec_step prog) o birs_symb_from_symbst;
   |>

!(x:word32) y.
  (x <+ x + 1w /\ (y + 1w <=+ x \/ x + 1w <=+ y)) ==>
  DISJOINT {bir_mem_addr Bit32 (w2n x)} {bir_mem_addr Bit32 (w2n y)}

!(x:word64) y.
  (x <+ x + 1w /\ (y + 1w <=+ x \/ x + 1w <=+ y)) ==>
  DISJOINT {bir_mem_addr Bit64 (w2n x)} {bir_mem_addr Bit64 (w2n y)}

!v e pc env status pcond.
  birs_symb_subst1 (v,e)
    <|bsst_pc := pc;
      bsst_environ := env;
      bsst_status := status;
      bsst_pcond := pcond|> =
  <|bsst_pc := pc;
    bsst_environ := birs_symb_env_subst1 v e env;
    bsst_status := status;
    bsst_pcond := bir_exp_subst1 v e pcond|>

!bprog bs L lbl1 env1 status pre cond lbl2 env2.
  (birs_symb_exec bprog
    (bs, L, {
      <|bsst_pc := lbl1;
        bsst_environ := env1;
        bsst_status := status;
        bsst_pcond := BExp_BinExp BIExp_And pre cond|>;
      <|bsst_pc := lbl2;
        bsst_environ := env2;
        bsst_status := BST_AssertionViolated;
        bsst_pcond := BExp_BinExp BIExp_And pre
                 (BExp_UnaryExp BIExp_Not cond)|>})) ==>
  (lbl1 <> lbl2 \/
   status <> BST_AssertionViolated) ==>
  (birs_pcondinf (BExp_BinExp BIExp_And pre
                 (BExp_UnaryExp BIExp_Not cond))) ==>
  (birs_symb_exec bprog
    (bs, L, {
      <|bsst_pc := lbl1;
        bsst_environ := env1;
        bsst_status := status;
        bsst_pcond := pre|>}))

!bprog bs L lbl1 env1 status1 pre cond lbl2 env2 status2.
  (birs_symb_exec bprog
    (bs, L, {
      <|bsst_pc := lbl1;
        bsst_environ := env1;
        bsst_status := status1;
        bsst_pcond := BExp_BinExp BIExp_And pre cond|>;
      <|bsst_pc := lbl2;
        bsst_environ := env2;
        bsst_status := status2;
        bsst_pcond := BExp_BinExp BIExp_And pre
                 (BExp_UnaryExp BIExp_Not cond)|>})) ==>
  (lbl1 <> lbl2 \/
   status1 <> status2) ==>
  (birs_pcondinf (BExp_BinExp BIExp_And pre cond)) ==>
  (birs_symb_exec bprog
    (bs, L, {
      <|bsst_pc := lbl2;
        bsst_environ := env2;
        bsst_status := status2;
        bsst_pcond := BExp_BinExp BIExp_And pre
                 (BExp_UnaryExp BIExp_Not cond)|>}))

!bprog bs L lbl1 env1 status1 pre cond lbl2 env2 status2.
  (birs_symb_exec bprog
    (bs, L, {
      <|bsst_pc := lbl1;
        bsst_environ := env1;
        bsst_status := status1;
        bsst_pcond := BExp_BinExp BIExp_And pre cond|>;
      <|bsst_pc := lbl2;
        bsst_environ := env2;
        bsst_status := status2;
        bsst_pcond := BExp_BinExp BIExp_And pre
                 (BExp_UnaryExp BIExp_Not cond)|>})) ==>
  (lbl1 <> lbl2 \/
   status1 <> status2) ==>
  (birs_pcondinf (BExp_BinExp BIExp_And pre
                 (BExp_UnaryExp BIExp_Not cond))) ==>
  (birs_symb_exec bprog
    (bs, L, {
      <|bsst_pc := lbl1;
        bsst_environ := env1;
        bsst_status := status1;
        bsst_pcond := BExp_BinExp BIExp_And pre cond|>}))

!prog bs L bs2 Pi pcond' bs2'.
   (bs2' =
     <|bsst_pc := bs2.bsst_pc;
       bsst_environ := bs2.bsst_environ;
       bsst_status := bs2.bsst_status;
       bsst_pcond := pcond'|>) ==>
    birs_symb_exec prog (bs, L, bs2 INSERT Pi) ==>
    birs_exp_imp bs2.bsst_pcond pcond' ==>
    birs_symb_exec prog (bs, L, bs2' INSERT Pi)

!prog L bs1' Pi pcond' bs1.
   (bs1 =
     <|bsst_pc := bs1'.bsst_pc;
       bsst_environ := bs1'.bsst_environ;
       bsst_status := bs1'.bsst_status;
       bsst_pcond := pcond'|>) ==>
    birs_symb_exec prog (bs1', L, Pi) ==>
    birs_exp_imp pcond' bs1'.bsst_pcond ==>
    birs_symb_symbols bs1 INTER birs_freesymbs bs1' Pi = EMPTY ==>
    birs_symb_exec prog (bs1, L, Pi)

!prog bs2 bs2' bs L lbl status pcond envl vn symbexp Pi symbexp'.
           (bs2 =
             <|bsst_pc := lbl;
               bsst_environ := birs_gen_env ((vn, symbexp)::envl);
               bsst_status := status;
               bsst_pcond := pcond|>) ==>
           (bs2' =
             <|bsst_pc := lbl;
               bsst_environ := birs_gen_env ((vn, symbexp')::envl);
               bsst_status := status;
               bsst_pcond := pcond|>) ==>
           birs_symb_exec prog (bs, L, bs2 INSERT Pi) ==>
           birs_simplification pcond symbexp symbexp' ==>
           birs_symb_exec prog (bs, L, bs2' INSERT (Pi DELETE bs2))

!prog bs2 bs2' bs L lbl status pcond envl vn symbexp Pi symbexp'.
           (bs2 =
             <|bsst_pc := lbl;
               bsst_environ := birs_gen_env ((vn, symbexp)::envl);
               bsst_status := status;
               bsst_pcond := pcond|>) ==>
           (bs2' =
             <|bsst_pc := lbl;
               bsst_environ := birs_gen_env ((vn, symbexp')::envl);
               bsst_status := status;
               bsst_pcond := pcond|>) ==>
           birs_symb_exec prog (bs, L, bs2 INSERT Pi) ==>
           birs_simplification pcond symbexp symbexp' ==>
           birs_symb_exec prog (bs, L, bs2' INSERT Pi)

!prog bs2 bs2' bs L lbl status pcond envl vn symbexp symbexp'.
           (bs2 =
             <|bsst_pc := lbl;
               bsst_environ := birs_gen_env ((vn, symbexp)::envl);
               bsst_status := status;
               bsst_pcond := pcond|>) ==>
           (bs2' =
             <|bsst_pc := lbl;
               bsst_environ := birs_gen_env ((vn, symbexp')::envl);
               bsst_status := status;
               bsst_pcond := pcond|>) ==>
           birs_symb_exec prog (bs, L, {bs2}) ==>
           birs_simplification pcond symbexp symbexp' ==>
           birs_symb_exec prog (bs, L, {bs2'})

